<script setup lang="ts">
import {computed, onMounted, onUnmounted, ref} from 'vue'
import {ArrowRight, Bot, Check, CheckCheck, ChevronRight, FileDiff, KeyRound, LockKeyhole, RefreshCw, Send, ShieldCheck, Sparkles, Undo2, X} from 'lucide-vue-next'
import {request} from '../api'
import type {Account} from '../types'

const props = defineProps<{accounts: Account[]; demo: boolean;admin:boolean}>()
type Channel = {kind: string; enabled: boolean; token: string; configured: boolean; chat_id: string; base_url: string; target_type: string; target_id: string; allow_private_http: boolean; clear_key?: boolean; account_ids?: string[]}
type Settings = {provider: {base_url: string; model: string; api_key: string; configured: boolean; allow_private_http: boolean; clear_key?: boolean; token_limit_field?: string}; channels: Channel[]; creative: boolean}
type Diff = {path: string; before: unknown; after: unknown}
type Plan = {id: string; account_id: string; target: string; summary: string; state: string; diff: Diff[]; before_hash: string; after_hash: string; created_at: string; expires_at: string; receipt: string; rollback_of: string}
type Delivery = {id: string; channel: string; state: string; detail: string; message: string; created_at: string}
const tab = ref('assistant'), selectedID = ref(''), target = ref('config'), intent = ref(''), busy = ref(false), error = ref(''), feedback = ref(''), acknowledge = ref(false), retryID = ref('')
const plans = ref<Plan[]>([]), selectedPlan = ref<Plan | null>(null), deliveries = ref<Delivery[]>([]), catalog = ref<Record<string, unknown> | null>(null)
const settings = ref<Settings>({provider: {base_url: '', model: '', api_key: '', configured: false, allow_private_http: false, token_limit_field: 'max_completion_tokens'}, channels: ['telegram', 'qq', 'astrbot'].map(kind => ({kind, enabled: false, token: '', configured: false, chat_id: '', base_url: '', target_type: 'private', target_id: '', allow_private_http: false})), creative: false})
const selected = computed(() => props.accounts.find(a => a.id === selectedID.value) || props.accounts[0])
const planAccount = computed(() => props.accounts.find(a => a.id === selectedPlan.value?.account_id))
const stateLabels: Record<string, string> = {draft:'待确认', queued:'等待 Windows 复核', dispatched:'Windows 正在处理', applied:'已应用并校验', blocked:'未应用', conflict:'配置已变化', rejected:'规则已拒绝', expired:'已过期', cancelled:'已取消', unknown:'待人工核实', queued_notification:'待发送', sending:'发送中', sent:'渠道已接收', failed:'发送失败'}
const channelNames: Record<string, string> = {telegram:'Telegram', qq:'QQ / OneBot', astrbot:'QQ 官方机器人 / AstrBot'}
function routeChannel(c: Channel, event: Event) {const id = (event.target as HTMLSelectElement).value; c.account_ids = id ? [id] : []}
const stateLabel = (state: string) => stateLabels[state] || state
const display = (v: unknown) => v === undefined || v === null ? '未设置' : typeof v === 'boolean' ? v ? '开启' : '关闭' : typeof v === 'object' ? JSON.stringify(v) : String(v)
const date = (s: string) => new Date(s).toLocaleString('zh-CN', {hour12: false})
const examples = computed(() => target.value === 'schedule' ? ['把第一班第一个贸易站的干员改为但书、清流、可露希尔，保留其他排班。', '第一班第一个宿舍暂时跳过，其他房间不变。'] : ['公开招募最多执行 4 次，保留其他设置。', '领取奖励时开启领取邮件，其他设置不变。', '库存保持按达成率补货，保留全部目标和资源预算。'])
let timer: ReturnType<typeof setInterval>
async function load(initial = false) {
 if (props.demo) return
 try {
  const [p, d] = await Promise.all([request<Plan[]>('/config/plans'), request<Delivery[]>('/integrations/notifications')]); plans.value = p; deliveries.value = d
  if (selectedPlan.value) selectedPlan.value = p.find(x => x.id === selectedPlan.value!.id) || selectedPlan.value
  if (initial) {const s = await request<Settings>('/integrations'); s.provider.api_key = ''; s.provider.token_limit_field ||= 'max_completion_tokens'; s.channels.forEach(c => c.token = ''); settings.value = s}
 } catch (e) {error.value = (e as Error).message}
}
async function run(action: () => Promise<void>) {if (busy.value) return; busy.value = true; error.value = ''; feedback.value = ''; try {await action()} catch (e) {error.value = (e as Error).message} finally {busy.value = false}}
async function propose() {
 if (!selected.value) return
 acknowledge.value = false
 await run(async () => {
  if (props.demo) {
   selectedPlan.value = {id: 'demo-plan', account_id: selected.value!.id, target: target.value, summary: '演示方案：仅展示确认流程，不请求模型或修改设备。', state: 'draft', diff: [{path: target.value === 'config' ? 'TaskQueue[3].MaxTimes' : 'plans[0].rooms.dormitory[0].skip', before: target.value === 'config' ? 3 : false, after: target.value === 'config' ? 4 : true}], before_hash: '演示指纹 / 非生产配置', after_hash: '', created_at: new Date().toISOString(), expires_at: new Date(Date.now() + 600000).toISOString(), receipt: '', rollback_of: ''}; return
  }
  selectedPlan.value = await request<Plan>(`/accounts/${selected.value!.id}/assistant/propose`, {method:'POST', body:JSON.stringify({intent:intent.value, target:target.value})}); await load()
 })
}
async function save() {await run(async () => {if (props.demo) {feedback.value = '演示模式不保存密钥或发送消息。'; return} await request('/integrations', {method:'PUT', body:JSON.stringify(settings.value)}); await load(true); feedback.value = '接入设置已保存，密钥已加密。'})}
async function test(kind: string, channel?: string) {await run(async () => {if (props.demo) {feedback.value = '演示模式不调用模型或发送通知。'; return} await request(`/integrations/${kind}/test${channel ? '?channel=' + encodeURIComponent(channel) : ''}`, {method:'POST', body:'{}'}); feedback.value = kind === 'provider' ? '指定模型与 JSON 响应已核实。' : '测试消息已排队，请查看下方送达记录。'; await load()})}
async function approve() {const p = selectedPlan.value; if (!p || !acknowledge.value) return; await run(async () => {if (props.demo) {p.state = 'applied'; p.receipt = '演示：模拟已备份、应用和校验。实际设备未变更。'; return} await request(`/config/plans/${p.id}/approve`, {method:'POST', body:JSON.stringify({confirm:p.id})}); await load(); feedback.value = '已确认差异，等待 Windows 端复核。'})}
async function planAction(p: Plan, action: string) {await run(async () => {if (props.demo) {feedback.value = '演示模式不控制实际设备。'; return} const result = await request<Plan>(`/config/plans/${p.id}/${action}`, {method:'POST', body:'{}'}); if (action === 'rollback') {selectedPlan.value = result; acknowledge.value = false; tab.value = 'assistant'} await load()})}
async function retry(id: string) {await run(async () => {if (!props.demo) await request(`/integrations/notifications/${id}/retry`, {method:'POST', body:JSON.stringify({confirm:true})}); retryID.value = ''; await load()})}
async function openRules() {tab.value = 'rules'; if (catalog.value) return; await run(async () => {catalog.value = props.demo ? {version:'maa-6.20-r1', invariants:['已知字段校验','未知字段保留','副号 0 药 / 0 石 / 48 小时临期窗口','差异确认、停止检测、指纹校验、备份、回滚'], unsupported:['账号身份与连接','定时计划与凭据','未验证版本']} : await request('/assistant/rules')})}
onMounted(() => {selectedID.value = props.accounts[0]?.id || ''; load(true); timer = setInterval(() => load(), 5000)})
onUnmounted(() => clearInterval(timer))
</script>

<template>
 <div class="assistant-workspace">
  <div class="agent-intro"><div class="agent-symbol"><Bot :size="30" :stroke-width="1.4"/></div><div><span class="eyebrow">// A LITTLE HELP WITH YOUR ROUTINE</span><h2>说出需求，核对后应用。</h2><p>让助手整理 MAA 设置；每一处改动，都有明确去向。</p></div><span class="agent-chip"><i class="tiny-square"></i>{{ settings.provider.configured ? '模型已配置' : '等待接入模型' }}</span></div>
  <div class="agent-tabs" role="tablist" aria-label="配置助手功能"><button role="tab" :aria-selected="tab === 'assistant'" @click="tab = 'assistant'"><Sparkles :size="16"/>配置助手</button><button role="tab" :aria-selected="tab === 'connections'" @click="tab = 'connections'"><KeyRound :size="16"/>我的接入与通知</button><button role="tab" :aria-selected="tab === 'rules'" @click="openRules"><ShieldCheck :size="16"/>规则库</button></div>
  <p class="inline-alert" role="alert" v-if="error">{{ error }}</p><p class="agent-feedback" role="status" v-if="feedback"><Check :size="16"/>{{ feedback }}</p>
  <div v-if="tab === 'assistant'" class="agent-grid">
   <section class="panel agent-request"><div class="panel-heading"><div><span class="eyebrow">01 / DESCRIBE</span><h2>这次想调整什么？</h2></div><Bot :size="20"/></div><form @submit.prevent="propose"><label>选择账号<select v-model="selectedID"><option v-for="a in accounts" :key="a.id" :value="a.id">{{ a.name }}</option></select></label><div class="agent-account-rule"><ShieldCheck :size="16"/><span>{{ selected?.role === 'secondary' ? '副号固定保护：普通药 0 · 源石 0 · 临期 48h' : '主号独立设置，资源预算只按明确需求修改' }}</span></div><label>修改范围<select v-model="target"><option value="config">任务与库存设置</option><option value="schedule">现有基建排班</option></select></label><label>用自己的话描述<textarea v-model="intent" rows="5" maxlength="2000" required placeholder="例如：公开招募最多执行 4 次，保留现有库存目标与排班。请勿填写密钥或密码。"></textarea></label><div class="agent-examples"><button v-for="example in examples" :key="example" type="button" @click="intent = example">{{ example }}<ArrowRight :size="13"/></button></div><p class="muted agent-privacy">发送内容包含本次需求、允许调整的业务字段和规则。账号登录信息、连接地址与密钥不会加入配置上下文。</p><button class="button primary wide" type="submit" :disabled="busy || !intent.trim() || !selected || (!demo && !settings.provider.configured)"><RefreshCw v-if="busy" :size="16" class="spinning"/><Sparkles v-else :size="16"/>{{ busy ? '正在整理方案…' : '生成修改方案' }}<ArrowRight :size="16"/></button><button v-if="!settings.provider.configured" class="text-button" type="button" @click="tab = 'connections'">先配置模型接入<ChevronRight :size="14"/></button></form></section>
   <section class="panel agent-review"><div class="panel-heading"><div><span class="eyebrow">02 / REVIEW</span><h2>核对每一处变化</h2></div><FileDiff :size="20"/></div><div v-if="!selectedPlan" class="agent-empty"><div class="empty-cross">+</div><h3>方案将在这里展开</h3><p>先描述需求，再查看原值与建议值。<br>确认之前，MAA 配置保持原样。</p><div class="agent-steps"><span>需求</span><ChevronRight :size="13"/><span>规则校验</span><ChevronRight :size="13"/><span>差异确认</span></div></div><div v-else class="agent-plan"><div class="agent-plan-meta"><strong>{{ planAccount?.name || selectedPlan.account_id }}</strong><span class="agent-chip">{{ stateLabel(selectedPlan.state) }}</span></div><p class="agent-summary">{{ selectedPlan.summary }}</p><div class="agent-diff" v-for="(d, n) in selectedPlan.diff" :key="n"><code>{{ d.path }}</code><div><span class="diff-before">{{ display(d.before) }}</span><ArrowRight :size="15"/><strong>{{ display(d.after) }}</strong></div></div><div class="agent-fingerprint"><span>源文件指纹</span><code>{{ selectedPlan.before_hash }}</code></div><p class="muted">预览有效至 {{ date(selectedPlan.expires_at) }}。关卡开放、干员持有和游戏内执行仍需实际验证。</p><div v-if="selectedPlan.state === 'draft'" class="agent-confirm"><p><LockKeyhole :size="16"/>应用前请正常退出 MAA，再刷新状态。Windows 端会再次检查、备份并校验。</p><label class="agent-check"><input type="checkbox" v-model="acknowledge"/>我已核对上述差异，确认应用到此账号。</label><button class="button primary wide" :disabled="busy || !acknowledge" @click="approve"><CheckCheck :size="17"/>确认并{{ selectedPlan.rollback_of ? '回滚' : '应用' }}<ArrowRight :size="16"/></button><button class="text-button" :disabled="busy" @click="planAction(selectedPlan, 'cancel')"><X :size="14"/>取消方案</button></div><p v-if="selectedPlan.receipt" class="agent-receipt"><ShieldCheck :size="17"/>{{ selectedPlan.receipt }}</p></div></section>
   <section class="panel agent-history"><div class="panel-heading"><div><span class="eyebrow">03 / KEEP A RECORD</span><h2>修改记录</h2></div><button class="text-button" :disabled="busy" @click="load()"><RefreshCw :size="14"/>刷新</button></div><div v-if="!plans.length" class="agent-history-empty">尚无实际修改记录。应用结果、冲突与回滚会保存在这里。</div><div class="agent-history-row" v-for="p in plans" :key="p.id"><button class="agent-history-main" @click="selectedPlan = p; acknowledge = false"><span>{{ accounts.find(a => a.id === p.account_id)?.name || p.account_id }}<small>{{ date(p.created_at) }} · {{ p.target === 'schedule' ? '基建排班' : '任务设置' }}</small></span><span>{{ stateLabel(p.state) }}<ChevronRight :size="15"/></span></button><button v-if="p.state === 'applied' && !p.rollback_of" class="text-button" :disabled="busy" @click="planAction(p, 'rollback')"><Undo2 :size="14"/>预览回滚</button></div></section>
  </div>
  <div v-else-if="tab === 'connections'" class="agent-grid settings-grid">
   <section class="panel agent-request"><div class="panel-heading"><div><span class="eyebrow">// MODEL CONNECTION</span><h2>OpenAI 兼容接口</h2></div><KeyRound :size="20"/></div><form @submit.prevent="save"><label>API 基址<input v-model="settings.provider.base_url" type="url" placeholder="https://your-provider.example/v1" autocomplete="off"/></label><label>确切模型名<input v-model="settings.provider.model" placeholder="填写服务商提供的完整模型标识" autocomplete="off"/></label><label>API Key<input v-model="settings.provider.api_key" type="password" autocomplete="new-password" :placeholder="settings.provider.configured ? '已保存；留空保留原密钥' : '输入 API Key'"/></label><label class="agent-check"><input type="checkbox" v-model="settings.provider.clear_key"/>清除已保存的模型密钥</label><label v-if="admin" class="agent-check"><input type="checkbox" v-model="settings.provider.allow_private_http"/>允许此内网接口（HTTP / HTTPS）</label><details class="agent-advanced"><summary>高级接口兼容选项</summary><label>输出限额参数<select v-model="settings.provider.token_limit_field"><option value="max_completion_tokens">max_completion_tokens（现代 OpenAI 接口）</option><option value="max_tokens">max_tokens（部分兼容服务）</option></select></label></details><p class="muted">接口需支持 JSON 响应。使用填写的确切型号，不自动替换或升级。测试与生成方案会消耗该接口额度。</p><div class="agent-button-row"><button class="button primary" :disabled="busy">保存接入设置<Check :size="16"/></button><button type="button" class="button" :disabled="busy || !settings.provider.configured" @click="test('provider')">测试已保存模型<ArrowRight :size="16"/></button></div></form><div class="agent-secret-note"><LockKeyhole :size="17"/><p>密钥加密保存在自己的控制中心。保存后无法从页面读回，备份时需保留配套加密密钥文件。</p></div></section>
   <section class="panel agent-request"><div class="panel-heading"><div><span class="eyebrow">// WHEN IT'S DONE</span><h2>消息送到你身边</h2></div><Send :size="20"/></div><form @submit.prevent="save"><div class="agent-channel" v-for="c in settings.channels" :key="c.kind"><div class="agent-channel-heading"><h3>{{ channelNames[c.kind] || c.kind }}</h3><label class="agent-check"><input type="checkbox" v-model="c.enabled"/>启用</label></div><template v-if="c.kind === 'telegram'"><label>Bot Token<input v-model="c.token" type="password" autocomplete="new-password" :placeholder="c.configured ? '已保存；留空保留' : '由 BotFather 创建的 Bot Token'"/></label><label>Chat ID<input v-model="c.chat_id" placeholder="数字 Chat ID（群通常为负数），或 @频道名" autocomplete="off"/></label><p class="muted">先在 Telegram 给机器人发送 /start；群聊需先将机器人加入群。仅填写用户名不能用于机器人私聊。</p></template><template v-else-if="c.kind === 'qq'"><label>OneBot HTTP 地址<input v-model="c.base_url" type="url" placeholder="http://内网 IP:端口"/></label><div class="agent-field-row"><label>接收方式<select v-model="c.target_type"><option value="private">QQ 私聊</option><option value="group">QQ 群</option></select></label><label>QQ / 群号码<input v-model="c.target_id" inputmode="numeric" placeholder="填写目标号码"/></label></div><label>Access Token<input v-model="c.token" type="password" autocomplete="new-password" :placeholder="c.configured ? '已保存；留空保留' : '与 OneBot 服务端一致'"/></label><label v-if="admin" class="agent-check"><input type="checkbox" v-model="c.allow_private_http"/>允许此内网 HTTP 服务</label></template>
     <template v-else-if="c.kind === 'astrbot'">
      <label>AstrBot 地址<input v-model="c.base_url" type="url" placeholder="http://内网 IP:6185" autocomplete="off"/></label>
      <label>接收会话 UMO<input v-model="c.target_id" maxlength="1024" placeholder="平台:FriendMessage:会话 ID" autocomplete="off"/></label>
      <p class="muted">在要接收通知的机器人私聊或群聊中发送 /sid，粘贴完整 UMO。QQ 官方机器人使用会话标识。</p>
      <label>AstrBot API Key<input v-model="c.token" type="password" autocomplete="new-password" :placeholder="c.configured ? '已保存；留空保留' : '在 AstrBot 设置中创建具有 im 权限的 Key'"/></label>
      <label v-if="admin" class="agent-check"><input type="checkbox" v-model="c.allow_private_http"/>允许此内网通知接口</label>
      <p class="muted">AstrBot 负责发送消息。QQ 官方平台可能限制主动消息的时段或次数，请以发送回执和实际收件为准。</p>
     </template>
     <label>接收账号<select :value="c.account_ids?.[0] || ''" @change="routeChannel(c, $event)"><option value="">全部账号</option><option v-for="a in accounts" :key="a.id" :value="a.id">仅 {{ a.name }}</option></select></label>
     <p class="muted">指定账号后，此接收端只收到该账号的记录。挂机开始通知一次，结束通知包含理智读数、本次执行和今日汇总；未采集的信息会注明。</p>
     <label class="agent-check"><input type="checkbox" v-model="c.clear_key"/>清除此渠道已保存的密钥</label>
     <button type="button" class="button" :aria-label="'仅测试已保存的 ' + (channelNames[c.kind] || c.kind)" :disabled="busy || !c.enabled || (c.kind !== 'qq' && !c.configured)" @click="test('notifications', c.kind)">测试已保存接入<Send :size="16"/></button>
    </div><label class="agent-check agent-creative"><input type="checkbox" v-model="settings.creative"/><span>让 Agent 为通知选择更自然的表达<small>任务状态、时间和校验结果始终由固定事实摘要提供。模型不可用时正常发送。</small></span></label><div class="agent-button-row"><button class="button primary" :disabled="busy">保存通知设置<Check :size="16"/></button><button type="button" class="button" :disabled="busy" @click="test('notifications')">测试全部已启用渠道<Send :size="16"/></button></div></form></section>
   <section class="panel agent-history"><div class="panel-heading"><div><span class="eyebrow">// DELIVERY RECEIPTS</span><h2>通知送达记录</h2></div><button class="text-button" @click="load()"><RefreshCw :size="14"/>刷新</button></div><p class="agent-history-empty" v-if="!deliveries.length">尚未发送通知。启用渠道并保存后，可以发送一条测试消息。</p><div class="agent-delivery" v-for="d in deliveries" :key="d.id"><div><strong>{{ channelNames[d.channel] || d.channel }} · {{ d.state === 'queued' ? '待发送' : stateLabel(d.state) }}</strong><small>{{ date(d.created_at) }} · {{ d.detail }}</small></div><details v-if="d.message"><summary>查看消息</summary><pre>{{ d.message }}</pre></details><button class="text-button" v-if="['failed', 'unknown'].includes(d.state)" @click="retryID = d.id">重试</button><div v-if="retryID === d.id" class="agent-retry"><p>请先核实收件端。重试可能产生重复消息。</p><button class="button" @click="retryID = ''">返回</button><button class="button primary" :disabled="busy" @click="retry(d.id)">已核实，重试</button></div></div></section>
  </div>
  <section v-else class="panel agent-rule-panel"><div class="panel-heading"><div><span class="eyebrow">// VERSIONED & CHECKED</span><h2>MAA 6.20 规则库</h2></div><ShieldCheck :size="21"/></div><div class="agent-rule-summary"><div><b>01</b><h3>限定修改范围</h3><p>仅调整已核实的任务业务字段与现有排班房间。保留未知字段、账号身份、连接与定时安排。</p></div><div><b>02</b><h3>资源约束独立检查</h3><p>副号普通药与源石固定为 0，临期窗口保持 48 小时。禁用任务同样参与校验。</p></div><div><b>03</b><h3>每次都有差异与备份</h3><p>确认后，Windows 端再次校验版本、进程与指纹。备份成功才写入，回滚也需确认差异。</p></div></div><p class="muted">当前规则针对已核实的 MAA 6.20。未支持的字段与版本会明确拒绝；不会自动放宽约束。</p><details><summary>查看完整规则定义</summary><pre>{{ JSON.stringify(catalog, null, 2) }}</pre></details><a class="text-button" href="https://github.com/yumi233/maa-control-center/blob/main/docs/agent-mode.md" target="_blank" rel="noopener noreferrer">查看操作说明<ArrowRight :size="15"/></a></section>
 </div>
</template>
